From 87c4b83e0fe234a1f0eed131ab6fa232036860d5 Mon Sep 17 00:00:00 2001
From: Anton Blanchard <anton@samba.org>
Date: Thu, 15 Jun 2017 09:46:38 +1000
Subject: [PATCH] powerpc: Fix emulation of mcrf in emulate_step()

The mcrf emulation code was using the CR field number directly as the shift
value, without taking into account that CR fields are numbered from 0-7 starting
at the high bits. That meant it was looking at the CR fields in the reverse
order.

Fixes: cf87c3f6b647 ("powerpc: Emulate icbi, mcrf and conditional-trap instructions")
Cc: stable@vger.kernel.org # v3.18+
Signed-off-by: Anton Blanchard <anton@samba.org>
Acked-by: Naveen N. Rao <naveen.n.rao@linux.vnet.ibm.com>
Signed-off-by: Michael Ellerman <mpe@ellerman.id.au>

diff --git a/arch/powerpc/lib/sstep.c b/arch/powerpc/lib/sstep.c
index 33117f8a0882..fb84f51b1f0b 100644
--- a/arch/powerpc/lib/sstep.c
+++ b/arch/powerpc/lib/sstep.c
@@ -683,8 +683,10 @@ int analyse_instr(struct instruction_op *op, struct pt_regs *regs,
 	case 19:
 		switch ((instr >> 1) & 0x3ff) {
 		case 0:		/* mcrf */
-			rd = (instr >> 21) & 0x1c;
-			ra = (instr >> 16) & 0x1c;
+			rd = 7 - ((instr >> 23) & 0x7);
+			ra = 7 - ((instr >> 18) & 0x7);
+			rd *= 4;
+			ra *= 4;
 			val = (regs->ccr >> ra) & 0xf;
 			regs->ccr = (regs->ccr & ~(0xfUL << rd)) | (val << rd);
 			goto instr_done;
-- 
2.25.1

### Modifications in Each File

**File: `arch/powerpc/lib/sstep.c`**
- The code for handling the `mcrf` instruction has been modified to correctly calculate the register field numbers.
- The original lines:
  ```c
  rd = (instr >> 21) & 0x1c;
  ra = (instr >> 16) & 0x1c;
  ```
  have been replaced with:
  ```c
  rd = 7 - ((instr >> 23) & 0x7);
  ra = 7 - ((instr >> 18) & 0x7);
  rd *= 4;
  ra *= 4;
  ```
- This change ensures that the `rd` and `ra` values are derived from the correct bits of the instruction, reflecting the proper order of the Condition Register (CR) fields.

### Relationships
- The modification addresses a bug where the `mcrf` emulation was incorrectly interpreting the CR field numbers, leading to the wrong bits being accessed. By adjusting the calculation of `rd` and `ra`, the patch fixes the issue of accessing CR fields in reverse order, ensuring that the emulation behaves as intended. This change is crucial for the correct functioning of the `mcrf` instruction in the PowerPC architecture.

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
powerpc: Fix emulation of mcrf in emulate_step()

The mcrf emulation code was using the CR field number directly as the shift
value, without taking into account that CR fields are numbered from 0-7 starting
at the high bits. That meant it was looking at the CR fields in the reverse
order.

Fixes: cf87c3f6b647 ("powerpc: Emulate icbi, mcrf and conditional-trap instructions")
Cc: stable@vger.kernel.org # v3.18+
Signed-off-by: Anton Blanchard <anton@samba.org>
Acked-by: Naveen N. Rao <naveen.n.rao@linux.vnet.ibm.com>
Signed-off-by: Michael Ellerman <mpe@ellerman.id.au>

Here is the root cause:
The bug was caused by the `mcrf` emulation code using the Condition Register (CR) field numbers directly as shift values without accounting for the fact that CR fields are numbered from 0 to 7 starting at the high bits. This led to the CR fields being accessed in reverse order, resulting in incorrect behavior during emulation.

Here is the patch:
  */
 int analyse_instr(struct instruction_op *op, struct pt_regs *regs,
 			    unsigned int instr)
 {
 	unsigned int opcode, ra, rb, rd, spr, u;
 	unsigned long int imm;
 	unsigned long int val, val2;
 	unsigned int mb, me, sh;
 	long ival;

 	op->type = COMPUTE;

 	opcode = instr >> 26;
 	switch (opcode) {
 	case 16:	/* bc */
 		op->type = BRANCH;
 		imm = (signed short)(instr & 0xfffc);
 		if ((instr & 2) == 0)
 			imm += regs->nip;
 		regs->nip += 4;
 		regs->nip = truncate_if_32bit(regs->msr, regs->nip);
 		if (instr & 1)
 			regs->link = regs->nip;
 		if (branch_taken(instr, regs))
 			regs->nip = truncate_if_32bit(regs->msr, imm);
 		return 1;
 #ifdef CONFIG_PPC64
 	case 17:	/* sc */
 		if ((instr & 0xfe2) == 2)
 			op->type = SYSCALL;
 		else
 			op->type = UNKNOWN;
 		return 0;
 #endif
 	case 18:	/* b */
 		op->type = BRANCH;
 		imm = instr & 0x03fffffc;
 		if (imm & 0x02000000)
 			imm -= 0x04000000;
 		if ((instr & 2) == 0)
 			imm += regs->nip;
 		if (instr & 1)
 			regs->link = truncate_if_32bit(regs->msr, regs->nip + 4);
 		imm = truncate_if_32bit(regs->msr, imm);
 		regs->nip = imm;
 		return 1;
 	case 19:
 		switch ((instr >> 1) & 0x3ff) {
 		case 0:		/* mcrf */
-			rd = (instr >> 21) & 0x1c;
-			ra = (instr >> 16) & 0x1c;
+			rd = 7 - ((instr >> 23) & 0x7);
+			ra = 7 - ((instr >> 18) & 0x7);
+			rd *= 4;
+			ra *= 4;
 			val = (regs->ccr >> ra) & 0xf;
 			regs->ccr = (regs->ccr & ~(0xfUL << rd)) | (val << rd);
 			goto instr_done;

 		case 16:	/* bclr */
 		case 528:	/* bcctr */
 			op->type = BRANCH;
 			imm = (instr & 0x400)? regs->ctr: regs->link;
 			regs->nip = truncate_if_32bit(regs->msr, regs->nip + 4);
 			imm = truncate_if_32bit(regs->msr, imm);
 			if (instr & 1)
 				regs->link = regs->nip;
 			if (branch_taken(instr, regs))
 				regs->nip = imm;
 			return 1;

 		case 18:	/* rfid, scary */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = RFI;
 			return 0;

 		case 150:	/* isync */
 			op->type = BARRIER;
 			isync();
 			goto instr_done;

 		case 33:	/* crnor */
 		case 129:	/* crandc */
 		case 193:	/* crxor */
 		case 225:	/* crnand */
 		case 257:	/* crand */
 		case 289:	/* creqv */
 		case 417:	/* crorc */
 		case 449:	/* cror */
 			ra = (instr >> 16) & 0x1f;
 			rb = (instr >> 11) & 0x1f;
 			rd = (instr >> 21) & 0x1f;
 			ra = (regs->ccr >> (31 - ra)) & 1;
 			rb = (regs->ccr >> (31 - rb)) & 1;
 			val = (instr >> (6 + ra * 2 + rb)) & 1;
 			regs->ccr = (regs->ccr & ~(1UL << (31 - rd))) |
 				(val << (31 - rd));
 			goto instr_done;
 		}
 		break;
 	case 31:
 		switch ((instr >> 1) & 0x3ff) {
 		case 598:	/* sync */
 			op->type = BARRIER;
 #ifdef __powerpc64__
 			switch ((instr >> 21) & 3) {
 			case 1:		/* lwsync */
 				asm volatile("lwsync" : : : "memory");
 				goto instr_done;
 			case 2:		/* ptesync */
 				asm volatile("ptesync" : : : "memory");
 				goto instr_done;
 			}
 #endif
 			mb();
 			goto instr_done;

 		case 854:	/* eieio */
 			op->type = BARRIER;
 			eieio();
 			goto instr_done;
 		}
 		break;
 	}

 	/* Following cases refer to regs->gpr[], so we need all regs */
 	if (!FULL_REGS(regs))
 		return 0;

 	rd = (instr >> 21) & 0x1f;
 	ra = (instr >> 16) & 0x1f;
 	rb = (instr >> 11) & 0x1f;

 	switch (opcode) {
 #ifdef __powerpc64__
 	case 2:		/* tdi */
 		if (rd & trap_compare(regs->gpr[ra], (short) instr))
 			goto trap;
 		goto instr_done;
 #endif
 	case 3:		/* twi */
 		if (rd & trap_compare((int)regs->gpr[ra], (short) instr))
 			goto trap;
 		goto instr_done;

 	case 7:		/* mulli */
 		regs->gpr[rd] = regs->gpr[ra] * (short) instr;
 		goto instr_done;

 	case 8:		/* subfic */
 		imm = (short) instr;
 		add_with_carry(regs, rd, ~regs->gpr[ra], imm, 1);
 		goto instr_done;

 	case 10:	/* cmpli */
 		imm = (unsigned short) instr;
 		val = regs->gpr[ra];
 #ifdef __powerpc64__
 		if ((rd & 1) == 0)
 			val = (unsigned int) val;
 #endif
 		do_cmp_unsigned(regs, val, imm, rd >> 2);
 		goto instr_done;

 	case 11:	/* cmpi */
 		imm = (short) instr;
 		val = regs->gpr[ra];
 #ifdef __powerpc64__
 		if ((rd & 1) == 0)
 			val = (int) val;
 #endif
 		do_cmp_signed(regs, val, imm, rd >> 2);
 		goto instr_done;

 	case 12:	/* addic */
 		imm = (short) instr;
 		add_with_carry(regs, rd, regs->gpr[ra], imm, 0);
 		goto instr_done;

 	case 13:	/* addic. */
 		imm = (short) instr;
 		add_with_carry(regs, rd, regs->gpr[ra], imm, 0);
 		set_cr0(regs, rd);
 		goto instr_done;

 	case 14:	/* addi */
 		imm = (short) instr;
 		if (ra)
 			imm += regs->gpr[ra];
 		regs->gpr[rd] = imm;
 		goto instr_done;

 	case 15:	/* addis */
 		imm = ((short) instr) << 16;
 		if (ra)
 			imm += regs->gpr[ra];
 		regs->gpr[rd] = imm;
 		goto instr_done;

 	case 20:	/* rlwimi */
 		mb = (instr >> 6) & 0x1f;
 		me = (instr >> 1) & 0x1f;
 		val = DATA32(regs->gpr[rd]);
 		imm = MASK32(mb, me);
 		regs->gpr[ra] = (regs->gpr[ra] & ~imm) | (ROTATE(val, rb) & imm);
 		goto logical_done;

 	case 21:	/* rlwinm */
 		mb = (instr >> 6) & 0x1f;
 		me = (instr >> 1) & 0x1f;
 		val = DATA32(regs->gpr[rd]);
 		regs->gpr[ra] = ROTATE(val, rb) & MASK32(mb, me);
 		goto logical_done;

 	case 23:	/* rlwnm */
 		mb = (instr >> 6) & 0x1f;
 		me = (instr >> 1) & 0x1f;
 		rb = regs->gpr[rb] & 0x1f;
 		val = DATA32(regs->gpr[rd]);
 		regs->gpr[ra] = ROTATE(val, rb) & MASK32(mb, me);
 		goto logical_done;

 	case 24:	/* ori */
 		imm = (unsigned short) instr;
 		regs->gpr[ra] = regs->gpr[rd] | imm;
 		goto instr_done;

 	case 25:	/* oris */
 		imm = (unsigned short) instr;
 		regs->gpr[ra] = regs->gpr[rd] | (imm << 16);
 		goto instr_done;

 	case 26:	/* xori */
 		imm = (unsigned short) instr;
 		regs->gpr[ra] = regs->gpr[rd] ^ imm;
 		goto instr_done;

 	case 27:	/* xoris */
 		imm = (unsigned short) instr;
 		regs->gpr[ra] = regs->gpr[rd] ^ (imm << 16);
 		goto instr_done;

 	case 28:	/* andi. */
 		imm = (unsigned short) instr;
 		regs->gpr[ra] = regs->gpr[rd] & imm;
 		set_cr0(regs, ra);
 		goto instr_done;

 	case 29:	/* andis. */
 		imm = (unsigned short) instr;
 		regs->gpr[ra] = regs->gpr[rd] & (imm << 16);
 		set_cr0(regs, ra);
 		goto instr_done;

 #ifdef __powerpc64__
 	case 30:	/* rld* */
 		mb = ((instr >> 6) & 0x1f) | (instr & 0x20);
 		val = regs->gpr[rd];
 		if ((instr & 0x10) == 0) {
 			sh = rb | ((instr & 2) << 4);
 			val = ROTATE(val, sh);
 			switch ((instr >> 2) & 3) {
 			case 0:		/* rldicl */
 				regs->gpr[ra] = val & MASK64_L(mb);
 				goto logical_done;
 			case 1:		/* rldicr */
 				regs->gpr[ra] = val & MASK64_R(mb);
 				goto logical_done;
 			case 2:		/* rldic */
 				regs->gpr[ra] = val & MASK64(mb, 63 - sh);
 				goto logical_done;
 			case 3:		/* rldimi */
 				imm = MASK64(mb, 63 - sh);
 				regs->gpr[ra] = (regs->gpr[ra] & ~imm) |
 					(val & imm);
 				goto logical_done;
 			}
 		} else {
 			sh = regs->gpr[rb] & 0x3f;
 			val = ROTATE(val, sh);
 			switch ((instr >> 1) & 7) {
 			case 0:		/* rldcl */
 				regs->gpr[ra] = val & MASK64_L(mb);
 				goto logical_done;
 			case 1:		/* rldcr */
 				regs->gpr[ra] = val & MASK64_R(mb);
 				goto logical_done;
 			}
 		}
 #endif
 	break; /* illegal instruction */

 	case 31:
 		switch ((instr >> 1) & 0x3ff) {
 		case 4:		/* tw */
 			if (rd == 0x1f ||
 			    (rd & trap_compare((int)regs->gpr[ra],
 					       (int)regs->gpr[rb])))
 				goto trap;
 			goto instr_done;
 #ifdef __powerpc64__
 		case 68:	/* td */
 			if (rd & trap_compare(regs->gpr[ra], regs->gpr[rb]))
 				goto trap;
 			goto instr_done;
 #endif
 		case 83:	/* mfmsr */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = MFMSR;
 			op->reg = rd;
 			return 0;
 		case 146:	/* mtmsr */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = MTMSR;
 			op->reg = rd;
 			op->val = 0xffffffff & ~(MSR_ME | MSR_LE);
 			return 0;
 #ifdef CONFIG_PPC64
 		case 178:	/* mtmsrd */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = MTMSR;
 			op->reg = rd;
 			/* only MSR_EE and MSR_RI get changed if bit 15 set */
 			/* mtmsrd doesn't change MSR_HV, MSR_ME or MSR_LE */
 			imm = (instr & 0x10000)? 0x8002: 0xefffffffffffeffeUL;
 			op->val = imm;
 			return 0;
 #endif

 		case 19:	/* mfcr */
 			regs->gpr[rd] = regs->ccr;
 			regs->gpr[rd] &= 0xffffffffUL;
 			goto instr_done;

 		case 144:	/* mtcrf */
 			imm = 0xf0000000UL;
 			val = regs->gpr[rd];
 			for (sh = 0; sh < 8; ++sh) {
 				if (instr & (0x80000 >> sh))
 					regs->ccr = (regs->ccr & ~imm) |
 						(val & imm);
 				imm >>= 4;
 			}
 			goto instr_done;

 		case 339:	/* mfspr */
 			spr = ((instr >> 16) & 0x1f) | ((instr >> 6) & 0x3e0);
 			switch (spr) {
 			case SPRN_XER:	/* mfxer */
 				regs->gpr[rd] = regs->xer;
 				regs->gpr[rd] &= 0xffffffffUL;
 				goto instr_done;
 			case SPRN_LR:	/* mflr */
 				regs->gpr[rd] = regs->link;
 				goto instr_done;
 			case SPRN_CTR:	/* mfctr */
 				regs->gpr[rd] = regs->ctr;
 				goto instr_done;
 			default:
 				op->type = MFSPR;
 				op->reg = rd;
 				op->spr = spr;
 				return 0;
 			}
 			break;

 		case 467:	/* mtspr */
 			spr = ((instr >> 16) & 0x1f) | ((instr >> 6) & 0x3e0);
 			switch (spr) {
 			case SPRN_XER:	/* mtxer */
 				regs->xer = (regs->gpr[rd] & 0xffffffffUL);
 				goto instr_done;
 			case SPRN_LR:	/* mtlr */
 				regs->link = regs->gpr[rd];
 				goto instr_done;
 			case SPRN_CTR:	/* mtctr */
 				regs->ctr = regs->gpr[rd];
 				goto instr_done;
 			default:
 				op->type = MTSPR;
 				op->val = regs->gpr[rd];
 				op->spr = spr;
 				return 0;
 			}
 			break;

 /*
  * Compare instructions
  */
 		case 0:	/* cmp */
 			val = regs->gpr[ra];
 			val2 = regs->gpr[rb];
 #ifdef __powerpc64__
 			if ((rd & 1) == 0) {
 				/* word (32-bit) compare */
 				val = (int) val;
 				val2 = (int) val2;
 			}
 #endif
 			do_cmp_signed(regs, val, val2, rd >> 2);
 			goto instr_done;

 		case 32:	/* cmpl */
 			val = regs->gpr[ra];
 			val2 = regs->gpr[rb];
 #ifdef __powerpc64__
 			if ((rd & 1) == 0) {
 				/* word (32-bit) compare */
 				val = (unsigned int) val;
 				val2 = (unsigned int) val2;
 			}
 #endif
 			do_cmp_unsigned(regs, val, val2, rd >> 2);
 			goto instr_done;

 /*
  * Arithmetic instructions
  */
 		case 8:	/* subfc */
 			add_with_carry(regs, rd, ~regs->gpr[ra],
 				       regs->gpr[rb], 1);
 			goto arith_done;
 #ifdef __powerpc64__
 		case 9:	/* mulhdu */
 			asm("mulhdu %0,%1,%2" : "=r" (regs->gpr[rd]) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;
 #endif
 		case 10:	/* addc */
 			add_with_carry(regs, rd, regs->gpr[ra],
 				       regs->gpr[rb], 0);
 			goto arith_done;

 		case 11:	/* mulhwu */
 			asm("mulhwu %0,%1,%2" : "=r" (regs->gpr[rd]) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;

 		case 40:	/* subf */
 			regs->gpr[rd] = regs->gpr[rb] - regs->gpr[ra];
 			goto arith_done;
 #ifdef __powerpc64__
 		case 73:	/* mulhd */
 			asm("mulhd %0,%1,%2" : "=r" (regs->gpr[rd]) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;
 #endif
 		case 75:	/* mulhw */
 			asm("mulhw %0,%1,%2" : "=r" (regs->gpr[rd]) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;

 		case 104:	/* neg */
 			regs->gpr[rd] = -regs->gpr[ra];
 			goto arith_done;

 		case 136:	/* subfe */
 			add_with_carry(regs, rd, ~regs->gpr[ra], regs->gpr[rb],
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 138:	/* adde */
 			add_with_carry(regs, rd, regs->gpr[ra], regs->gpr[rb],
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 200:	/* subfze */
 			add_with_carry(regs, rd, ~regs->gpr[ra], 0L,
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 202:	/* addze */
 			add_with_carry(regs, rd, regs->gpr[ra], 0L,
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 232:	/* subfme */
 			add_with_carry(regs, rd, ~regs->gpr[ra], -1L,
 				       regs->xer & XER_CA);
 			goto arith_done;
 #ifdef __powerpc64__
 		case 233:	/* mulld */
 			regs->gpr[rd] = regs->gpr[ra] * regs->gpr[rb];
 			goto arith_done;
 #endif
 		case 234:	/* addme */
 			add_with_carry(regs, rd, regs->gpr[ra], -1L,
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 235:	/* mullw */
 			regs->gpr[rd] = (unsigned int) regs->gpr[ra] *
 				(unsigned int) regs->gpr[rb];
 			goto arith_done;

 		case 266:	/* add */
 			regs->gpr[rd] = regs->gpr[ra] + regs->gpr[rb];
 			goto arith_done;
 #ifdef __powerpc64__
 		case 457:	/* divdu */
 			regs->gpr[rd] = regs->gpr[ra] / regs->gpr[rb];
 			goto arith_done;
 #endif
 		case 459:	/* divwu */
 			regs->gpr[rd] = (unsigned int) regs->gpr[ra] /
 				(unsigned int) regs->gpr[rb];
 			goto arith_done;
 #ifdef __powerpc64__
 		case 489:	/* divd */
 			regs->gpr[rd] = (long int) regs->gpr[ra] /
 				(long int) regs->gpr[rb];
 			goto arith_done;
 #endif
 		case 491:	/* divw */
 			regs->gpr[rd] = (int) regs->gpr[ra] /
 				(int) regs->gpr[rb];
 			goto arith_done;


 /*
  * Logical instructions
  */
 		case 26:	/* cntlzw */
 			asm("cntlzw %0,%1" : "=r" (regs->gpr[ra]) :
 			    "r" (regs->gpr[rd]));
 			goto logical_done;
 #ifdef __powerpc64__
 		case 58:	/* cntlzd */
 			asm("cntlzd %0,%1" : "=r" (regs->gpr[ra]) :
 			    "r" (regs->gpr[rd]));
 			goto logical_done;
 #endif
 		case 28:	/* and */
 			regs->gpr[ra] = regs->gpr[rd] & regs->gpr[rb];
 			goto logical_done;

